using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
[InitializeOnLoad]public static class AtelierEditor {
 public static readonly string Root=Path.GetFullPath(Path.Combine(Application.dataPath,"../Builds/PartnerTools")).Replace('\\','/');public const string Scene="Assets/Atelier/Scenes/SteamAtelier.unity";static double next;
 static AtelierEditor(){Directory.CreateDirectory(Root+"/Reports");EditorApplication.update+=Poll;}
 static void Poll(){if(EditorApplication.timeSinceStartup<next||EditorApplication.isCompiling||EditorApplication.isUpdating)return;next=EditorApplication.timeSinceStartup+.8;string path=Root+"/Reports/command.txt";if(!File.Exists(path))return;string command=File.ReadAllText(path).Trim();if(EditorApplication.isPlayingOrWillChangePlaymode&&command!="refresh"&&command!="shot"){EditorApplication.isPlaying=false;return;}File.Delete(path);try{if(command=="refresh")AssetDatabase.Refresh();if(command=="inspect")Inspect();if(command=="audit")Audit();if(command=="build")AtelierBuild.Run();if(command=="preview")AtelierPreview.Run();if(command=="reviewA")AtelierReviewA.Run();if(command=="qa")AtelierQA.Run();if(command=="player")AtelierQA.BuildPlayer();if(command=="shot")ScreenCapture.CaptureScreenshot(Root+"/Reports/manual.png");}catch(Exception e){File.WriteAllText(Root+"/Reports/error.txt",e.ToString());Debug.LogException(e);}}
 [Serializable]class Item{public string path,id,title;public Vector3 position,scale,boundsCenter,boundsSize;public string[] materials;public string mesh;}
 [Serializable]class Dump{public Item[] parts,meshes;public string[] roots,pieces;}
 public static void Audit(){EditorSceneManager.OpenScene(Scene);var rows=UnityEngine.Object.FindObjectsOfType<MeshRenderer>(true).Select(r=>{var m=r.GetComponent<MeshFilter>();return new Item{path=r.transform.parent.name+"/"+r.name,position=r.transform.position,scale=r.transform.lossyScale,boundsCenter=r.bounds.center,boundsSize=r.bounds.size,materials=r.sharedMaterials.Select(mat=>mat?mat.name:"NULL").ToArray(),mesh=m?AssetDatabase.GetAssetPath(m.sharedMesh):""};}).ToArray();File.WriteAllText(Root+"/Reports/audit-meshes.json",JsonUtility.ToJson(new Dump{meshes=rows},true));}
 public static void Inspect(){EditorSceneManager.OpenScene("Assets/Locomotive/Scenes/FreeAssembly.unity");var e=UnityEngine.Object.FindObjectOfType<LocomotiveController>();var w=e.GetComponent<LocomotiveFreeAssembly>();Func<Transform,string> path=null;path=t=>t.parent?path(t.parent)+"/"+t.name:t.name;
 var d=new Dump{roots=UnityEngine.SceneManagement.SceneManager.GetActiveScene().GetRootGameObjects().Select(g=>g.name).ToArray(),pieces=w.pieces.Select(p=>p.key+" | "+p.title+" | "+string.Join(",",p.members.Select(m=>m.partId))).ToArray(),parts=e.parts.Select(p=>new Item{path=path(p.transform),id=p.partId,title=p.title,position=p.home,scale=p.transform.localScale}).ToArray(),meshes=e.locomotive.GetComponentsInChildren<MeshRenderer>(true).Select(r=>new Item{path=path(r.transform),position=r.transform.localPosition,scale=r.transform.localScale,boundsCenter=r.bounds.center,boundsSize=r.bounds.size,materials=r.sharedMaterials.Select(m=>m?m.name:"NULL").ToArray(),mesh=AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>()?.sharedMesh)}).ToArray()};File.WriteAllText(Root+"/Reports/inspection.json",JsonUtility.ToJson(d,true));Debug.Log("ATELIER_INSPECTION_COMPLETE");}
}


